      for (const e of graph.edges.filter((e) => e.source === id)) {
        const d = (indegree.get(e.target) ?? 0) - 1;
        indegree.set(e.target, d);
        if (d === 0) queue.push(e.target);
      }
    }
    expect(visited).toBe(graph.nodes.length);
  });
});

