cat >> packages/core/src/scoring.ts <<'EOF'

/** The documented formula: 100 × Σ(weight × value) / (5 × Σ weight), rounded to one decimal. */
export function weightedTotal(
  values: Record<ScoreFactor, number>,
  weights: Record<ScoreFactor, number>,
): number {
  let num = 0;
  let den = 0;
  for (const f of ScoreFactor.options) {
    const v = values[f];
    const w = weights[f];
    if (!(v >= 0 && v <= 5)) throw new RangeError(`Factor ${f} must be within 0–5, got ${v}`);
    if (!(w >= 0)) throw new RangeError(`Weight for ${f} must be ≥ 0, got ${w}`);
    num += w * v;
    den += 5 * w;
  }
  if (den === 0) throw new RangeError("At least one score weight must be > 0");
  return Math.round((1000 * num) / den) / 10;
}

export function priorityForScore(total: number, t: PriorityThresholds): Priority {
  if (total >= t.must) return "must";
  if (total >= t.should) return "should";
  if (total >= t.could) return "could";
  return "wont";
}
EOF
cat > packages/core/src/scoring.test.ts <<'EOF'
import { describe, expect, it } from "vitest";
import { priorityForScore, weightedTotal } from "./scoring";
import { DEFAULT_SETTINGS } from "./settings";

const { weights, thresholds } = DEFAULT_SETTINGS.scoring;
const all = (v: number) =>
  ({ customer_impact: v, evidence_strength: v, competitive_gap: v, trend_momentum: v, brand_fit: v, ease: v });

describe("scoring formula", () => {
  it("maps 0–5 factor values onto 0–100", () => {
    expect(weightedTotal(all(0), weights)).toBe(0);
    expect(weightedTotal(all(5), weights)).toBe(100);
    expect(weightedTotal(all(2.5), weights)).toBe(50);
  });

  it("rejects out-of-range values and all-zero weights", () => {
    expect(() => weightedTotal(all(6), weights)).toThrow(RangeError);
    expect(() => weightedTotal(all(3), all(0))).toThrow(/weight/);
  });

  it("bands totals with the default thresholds", () => {
    expect(priorityForScore(70, thresholds)).toBe("must");
    expect(priorityForScore(69.9, thresholds)).toBe("should");
    expect(priorityForScore(30, thresholds)).toBe("could");
    expect(priorityForScore(29.9, thresholds)).toBe("wont");
  });
});
EOF
