export function boundaryBlocks(parentId: string, ports: BlockPorts): WorkflowBlock[] {
  return [
    ...ports.inputs.map(
      (port, i): WorkflowBlock => ({
        id: boundaryBlockId(parentId, port.id),
        kind: "block_input",
        label: port.label,
        position: { x: 0, y: i * BOUNDARY_ROW_GAP },
        params: { port: port.id },
