import type {
  AuditLogger,
  BlockParams,
  FileStore,
  LlmClient,
  PaletteBlockKind,
  PipelineData,
  ProductScope,
  Requirement,
  Settings,
  WebSearch,
} from "@reqflow/core";

/** Everything a block may touch while running. Blocks must not import DB, env or Electron code. */
export interface BlockContext {
  runId: string;
  blockId: string;
  scope: ProductScope; // the run's scope; params set to "From Settings" resolve to it
  settings: Settings; // snapshot taken when the run started
  llm: LlmClient;
  audit: AuditLogger; // record what the block created or changed, actor { type: "ai", component: <kind> }
  files: FileStore;
  web: WebSearch | null; // null when Settings.research.provider === "off"
  /** Requirements handed to the Car page (Add to Car). WS1 wires this to the database. */
  car: { add(requirements: Requirement[]): Promise<void> };
  log(message: string): void; // shown on the block in the editor
  progress(fraction: number, message?: string): void; // 0–1
  signal: AbortSignal; // run cancelled → stop promptly
  resumed: boolean; // true when a HIL block is re-entered after the reviewer finished
}

/** What arrived, per input port id. Several edges into one port are merged with `mergePipelineData`. */
export type BlockInputs = Record<string, PipelineData>;

export type BlockResult =
  /** Exactly one entry per output port id (`blockPorts(block).outputs`). Sinks return `{}`. */
  | { status: "ok"; outputs: Record<string, PipelineData> }
  /** Only HIL pauses. The engine marks the run `waiting_for_review` and re-runs the block on resume. */
  | { status: "paused"; message: string };

export interface BlockImplementation<K extends PaletteBlockKind = PaletteBlockKind> {
  kind: K;
  /**
   * `params` are already validated with `parseBlockParams(kind, …)`. Must be deterministic given
   * (inputs, params, LLM output) and must throw on bad input: no silent skips.
   */
  run(inputs: BlockInputs, params: BlockParams, ctx: BlockContext): Promise<BlockResult>;
}

/** Identity helper that keeps `kind` literal. */
export function defineBlock<K extends PaletteBlockKind>(
  impl: BlockImplementation<K>,
): BlockImplementation<K> {
  return impl;
}
EOF
cat > packages/engine/src/registry.ts <<'EOF'
import { isPaletteBlockKind, PALETTE_BLOCK_KINDS, type PaletteBlockKind } from "@reqflow/core";
import type { BlockImplementation } from "./block";

/**
 * Block kinds that never need an implementation: a custom block only runs its inner workplace.
 * (Specs, ports and params of every kind live in `@reqflow/core` → BLOCK_SPECS.)
 */
export const SUBFLOW_ONLY_KINDS: readonly PaletteBlockKind[] = ["custom"];

export class BlockRegistry {
  private readonly impls = new Map<PaletteBlockKind, BlockImplementation>();

  constructor(impls: readonly BlockImplementation[] = []) {
    for (const impl of impls) this.register(impl);
  }

  register(impl: BlockImplementation): void {
    if (!isPaletteBlockKind(impl.kind)) throw new Error(`Unknown block kind "${impl.kind}"`);
    if (SUBFLOW_ONLY_KINDS.includes(impl.kind)) {
      throw new Error(`"${impl.kind}" blocks only run their inner workplace`);
    }
    if (this.impls.has(impl.kind)) {
      throw new Error(`Block kind "${impl.kind}" is already registered`);
    }
    this.impls.set(impl.kind, impl);
  }

  get(kind: PaletteBlockKind): BlockImplementation {
    const impl = this.impls.get(kind);
    if (!impl) throw new Error(`Block kind "${kind}" has no implementation yet`);
    return impl;
  }

  has(kind: PaletteBlockKind): boolean {
    return this.impls.has(kind);
  }

  /** Kinds that still need an implementation, for status reporting. */
  missing(): PaletteBlockKind[] {
    return PALETTE_BLOCK_KINDS.filter((k) => !SUBFLOW_ONLY_KINDS.includes(k) && !this.has(k));
  }
}
EOF
