import { memo } from "react";
import { Handle, Position, type NodeProps } from "@xyflow/react";
import type { BlockFlowNode } from "./flow";
import { BlockIcon } from "./BlockIcon";
import { GROUP_STYLE } from "./groups";
import { dataflowStore } from "./store";
import { isBoundaryBlockKind, type SelectOption } from "@reqflow/core";
import { cx } from "@/lib/cx";

export const BlockNode = memo(function BlockNode({ data, selected }: NodeProps<BlockFlowNode>) {
  const { block, ports, spec } = data;

  if (!spec) return null; // Should not happen for BlockNode, caught by flow types

  const style = GROUP_STYLE[spec.group];
  const isRenamed = block.label !== spec.label;

  const innerBlocks = block.inner?.blocks.filter((b) => !isBoundaryBlockKind(b.kind)) ?? [];
  const innerCountText =
    innerBlocks.length === 0
      ? "Empty inside"
      : `${innerBlocks.length} block${innerBlocks.length === 1 ? "" : "s"} inside`;

  // One-line param summary: first two select params
  const selectParams = spec.params.filter((p) => p.type === "select" || p.type === "multiselect");
  const summaryLabels = selectParams
    .slice(0, 2)
    .map((p) => {
      const val = block.params[p.key];
      if (p.type === "select") {
        if (val === "global") return "From Settings";
        const opt = (p as any).options.find((o: SelectOption) => o.value === val);
        return opt ? opt.label : String(val);
      }
      if (p.type === "multiselect" && Array.isArray(val)) {
        return val.length === 0 ? "None" : `${val.length} selected`;
      }
      return null;
    })
    .filter(Boolean);

  const numRows = Math.max(ports.inputs.length, ports.outputs.length);

  return (
    <div
      data-testid={`block-${block.kind}`}
      data-block-id={block.id}
      className={cx(
        "w-56 rounded-xl border bg-panel shadow-sm transition-shadow",
        selected ? "border-brand ring-2 ring-brand/30" : "border-line",
      )}
    >
      <div className="flex items-start justify-between p-3 pb-2">
        <div className="flex items-center gap-3 overflow-hidden">
          <div
            className={cx(
              "flex size-8 shrink-0 items-center justify-center rounded-lg",
              style.tile,
            )}
          >
            <BlockIcon kind={block.kind as any} className="size-5" />
          </div>
          <div className="flex flex-col overflow-hidden">
            <span className="truncate text-sm font-medium text-ink" title={block.label}>
              {block.label}
            </span>
            <span
              className="truncate text-xs text-muted"
              title={isRenamed ? spec.label : style.name}
            >
              {isRenamed ? spec.label : style.name}
            </span>
          </div>
        </div>

        {spec.hasInnerWorkplace && (
          <button
            type="button"
            data-testid="block-expand"
            className="nodrag shrink-0 rounded-md p-1 text-muted hover:bg-panel-2 hover:text-ink"
            aria-label={`Open the inside of ${block.label}`}
            onClick={(e) => {
              e.stopPropagation();
              dataflowStore.getState().openInner(block.id);
            }}
          >
            <svg
              xmlns="http://www.w3.org/2000/svg"
              width="16"
              height="16"
              viewBox="0 0 24 24"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <path d="M15 3h6v6M9 21H3v-6M21 3l-7 7M3 21l7-7" />
            </svg>
          </button>
        )}
      </div>

      {(spec.hasInnerWorkplace || summaryLabels.length > 0) && (
        <div className="px-3 pb-2 text-xs text-muted">
          {spec.hasInnerWorkplace && <div>{innerCountText}</div>}
          {summaryLabels.length > 0 && <div className="truncate">{summaryLabels.join(" · ")}</div>}
        </div>
      )}

      {numRows > 0 && (
        <div className="flex flex-col py-2 border-t border-line">
          {Array.from({ length: numRows }).map((_, i) => {
            const input = ports.inputs[i];
            const output = ports.outputs[i];

            return (
              <div
                key={i}
                className="relative flex h-7 w-full items-center justify-between px-3 text-xs text-ink"
              >
                {input ? (
                  <>
                    <Handle
                      type="target"
                      position={Position.Left}
                      id={input.id}
                      className={cx("!size-2.5 !border-2 !bg-panel", style.border, "-ml-px")}
                    />
                    <span className="truncate pr-2">{input.label}</span>
                  </>
                ) : (
                  <span />
                )}

                {output ? (
                  <>
                    <span className="truncate pl-2 text-right">{output.label}</span>
                    <Handle
                      type="source"
                      position={Position.Right}
                      id={output.id}
                      className={cx("!size-2.5 !border-2 !bg-panel", style.border, "-mr-px")}
                    />
                  </>
                ) : (
                  <span />
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
});
import { memo } from "react";
import { Handle, Position, type NodeProps } from "@xyflow/react";
import type { BlockFlowNode } from "./flow";
import { BlockIcon } from "./BlockIcon";

export const BoundaryNode = memo(function BoundaryNode({ data }: NodeProps<BlockFlowNode>) {
  const { block, ports } = data;
  const isInput = block.kind === "block_input";

  return (
    <div
      data-testid={`boundary-${isInput ? "input" : "output"}`}
      data-block-id={block.id}
      className="flex items-center gap-2 rounded-full border-2 border-dashed border-line-strong bg-panel px-4 py-2 shadow-sm"
    >
      {isInput && (
        <Handle
          type="source"
          position={Position.Right}
          id={ports.outputs[0]?.id || "out"}
          className="!size-2.5 !border-2 !border-line-strong !bg-panel"
        />
      )}
      {!isInput && (
        <Handle
          type="target"
          position={Position.Left}
          id={ports.inputs[0]?.id || "in"}
          className="!size-2.5 !border-2 !border-line-strong !bg-panel"
        />
      )}

      <BlockIcon
        kind={block.kind as "block_input" | "block_output"}
        className="size-5 text-muted"
      />
      <div className="flex flex-col">
        <span className="text-sm font-medium text-ink">
          {isInput ? ports.outputs[0]?.label : ports.inputs[0]?.label}
        </span>
        <span className="text-xs text-muted">{isInput ? "From outside" : "To outside"}</span>
      </div>
    </div>
  );
});
import type { BlockGroup } from "@reqflow/core";

export const GROUP_STYLE: Record<
  BlockGroup,
  { name: string; text: string; tile: string; border: string }
> = {
  structure: {
    name: "Structure",
    text: "text-group-structure",
    tile: "bg-group-structure/10 text-group-structure",
    border: "!border-group-structure",
  },
  source: {
    name: "Source",
    text: "text-group-source",
    tile: "bg-group-source/10 text-group-source",
    border: "!border-group-source",
  },
  ai: {
    name: "AI",
    text: "text-group-ai",
    tile: "bg-group-ai/10 text-group-ai",
    border: "!border-group-ai",
  },
  human: {
    name: "Human",
    text: "text-group-human",
    tile: "bg-group-human/10 text-group-human",
    border: "!border-group-human",
  },
  output: {
    name: "Output",
    text: "text-group-output",
    tile: "bg-group-output/10 text-group-output",
    border: "!border-group-output",
  },
};
import { useMemo } from "react";
import { useDataflow, dataflowStore, breadcrumbOf } from "./store";

export function Breadcrumb() {
  const root = useDataflow((s) => s.root);
  const path = useDataflow((s) => s.path);

  const crumbs = useMemo(() => breadcrumbOf(root, path), [root, path]);

  return (
    <div data-testid="breadcrumb" className="flex items-center gap-1.5 text-sm">
      {crumbs.map((crumb, i) => {
        const isLast = i === crumbs.length - 1;
        return (
          <div key={crumb.depth} className="flex items-center gap-1.5">
            {i > 0 && <span className="text-muted">›</span>}
            {isLast ? (
              <span className="font-medium text-ink">{crumb.label}</span>
            ) : (
              <button
                type="button"
                data-testid={`crumb-${crumb.depth}`}
                className="text-muted hover:text-ink transition-colors"
                onClick={() => dataflowStore.getState().goTo(crumb.depth)}
              >
                {crumb.label}
              </button>
            )}
          </div>
        );
      })}
    </div>
  );
}
import { useEffect } from "react";
import { useDataflow, dataflowStore } from "./store";
import { cx } from "@/lib/cx";

export function NoticeToast() {
  const notice = useDataflow((s) => s.notice);

  useEffect(() => {
    if (!notice) return;
    const timer = setTimeout(() => {
      dataflowStore.getState().dismissNotice();
    }, 5000);
    return () => clearTimeout(timer);
  }, [notice?.id]);

  if (!notice) return null;

  const isError = notice.tone === "error";

  return (
    <div
      data-testid="notice"
      role={isError ? "alert" : "status"}
      className={cx(
        "absolute bottom-4 left-1/2 -translate-x-1/2 flex items-center gap-3 px-4 py-2 rounded-lg shadow-lg text-sm border",
        isError ? "bg-danger-soft text-danger border-danger/20" : "bg-panel-2 text-ink border-line",
      )}
    >
      <span>{notice.message}</span>
      <button
        type="button"
        className="opacity-70 hover:opacity-100"
        onClick={() => dataflowStore.getState().dismissNotice()}
