import { useState } from "react";
import { useDataflow, dataflowStore, selectInspectedBlock } from "./store";
import { BlockIcon } from "./BlockIcon";
import { ParamField } from "./ParamField";
import { TextInput } from "../ui/controls";
import { Button } from "../ui/Button";
import { GROUP_STYLE } from "./groups";
import { useSettings } from "@/lib/settings";
import { BLOCK_SPECS, isBoundaryBlockKind, isParamVisible, blockPorts } from "@reqflow/core";

export function Inspector() {
  const block = useDataflow(selectInspectedBlock);
  const settings = useSettings((s) => s.settings);

  // Rename error state
  const [renameError, setRenameError] = useState<string | null>(null);

  if (!block) return null;

  const isBoundary = isBoundaryBlockKind(block.kind);
  const spec = isBoundary ? null : BLOCK_SPECS[block.kind as keyof typeof BLOCK_SPECS];

  const handleDelete = () => {
    if (settings.app.confirmBeforeDelete) {
      if (
        !window.confirm(
          `Delete "${block.label}"?\n\nIts connections and everything inside its workplace will also be deleted.`,
        )
      ) {
        return;
      }
    }
    dataflowStore.getState().deleteSelection();
  };

  if (isBoundary) {
    const isInput = block.kind === "block_input";
    const ports = blockPorts(block as any);
    const portLabel = isInput
      ? (ports.outputs?.[0]?.label ?? "Output")
      : (ports.inputs?.[0]?.label ?? "Input");

    return (
      <div
        data-testid="inspector"
        className="absolute bottom-2 right-2 top-2 flex w-80 flex-col rounded-xl border border-line bg-panel shadow-lg"
      >
        <div className="flex items-center justify-between border-b border-line p-4">
          <div className="flex items-center gap-3">
            <BlockIcon
              kind={block.kind as "block_input" | "block_output"}
              className="size-5 text-muted"
            />
            <span className="font-medium text-ink">{isInput ? "Input" : "Output"}</span>
          </div>
          <button
            type="button"
            className="text-muted hover:text-ink"
            onClick={() => dataflowStore.getState().selectBlock(null)}
          >
            <svg
              xmlns="http://www.w3.org/2000/svg"
              width="20"
              height="20"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <path d="M18 6L6 18M6 6l12 12" />
            </svg>
          </button>
        </div>
        <div className="p-4 text-sm text-muted">
          {isInput
            ? `What arrives at this block's ${block.label} input enters the inner workplace here.`
            : `What reaches this block leaves the inner workplace on ${block.label}.`}
        </div>
      </div>
    );
  }

  // Regular palette block
  const style = GROUP_STYLE[spec!.group];

  const handleRename = (label: string) => {
    const error = dataflowStore.getState().renameBlock(block.id, label);
    setRenameError(error);
  };

  const innerCount = block.inner
    ? block.inner.blocks.filter((b) => !isBoundaryBlockKind(b.kind)).length
    : 0;

  const ports = spec!.ports(block.params);
  const inputsText = ports.inputs.length > 0 ? ports.inputs.map((p) => p.label).join(", ") : "none";
  const outputsText =
    ports.outputs.length > 0 ? ports.outputs.map((p) => p.label).join(", ") : "none";

  return (
    <div
      data-testid="inspector"
      className="absolute bottom-2 right-2 top-2 flex w-80 flex-col overflow-y-auto rounded-xl border border-line bg-panel shadow-lg"
    >
      <div className="flex flex-col gap-4 border-b border-line p-4">
        <div className="flex items-start justify-between">
          <div className="flex items-center gap-3">
            <div
              className={`flex size-8 shrink-0 items-center justify-center rounded-lg ${style.tile}`}
            >
              <BlockIcon kind={block.kind as any} className="size-5" />
            </div>
            <div className="flex flex-col">
              <span className="text-sm font-medium text-ink">{spec!.label}</span>
              <span className="text-xs text-muted">{style.name}</span>
            </div>
          </div>
          <button
            type="button"
            className="text-muted hover:text-ink"
            onClick={() => dataflowStore.getState().selectBlock(null)}
          >
            <svg
              xmlns="http://www.w3.org/2000/svg"
              width="20"
              height="20"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeLinejoin="round"
            >
              <path d="M18 6L6 18M6 6l12 12" />
            </svg>
          </button>
        </div>

        <div>
          <TextInput value={block.label} onChange={handleRename} />
          {renameError && <div className="mt-1 text-xs text-danger">{renameError}</div>}
        </div>
      </div>

      <div className="flex flex-col gap-6 p-4">
        <div className="text-sm text-muted">{spec!.description}</div>

        <div className="flex flex-col gap-1 text-sm">
          <div>
            <span className="font-medium text-ink">Inputs:</span>{" "}
            <span className="text-muted">{inputsText}</span>
          </div>
          <div>
            <span className="font-medium text-ink">Outputs:</span>{" "}
            <span className="text-muted">{outputsText}</span>
          </div>
        </div>

        {spec!.hasInnerWorkplace && (
          <Button
            data-testid="inspector-open-inner"
            variant="secondary"
            onClick={() => dataflowStore.getState().openInner(block.id)}
          >
            Open its workplace ({innerCount})
          </Button>
        )}

        <div className="flex flex-col gap-4">
          <h3 className="text-sm font-medium text-ink">Parameters</h3>
          {spec!.params.length === 0 ? (
            <div className="text-sm text-muted">
              No parameters. Build this block's logic in its workplace.
            </div>
          ) : (
            spec!.params
              .filter((p) => isParamVisible(p, block.params))
              .map((p) => <ParamField key={p.key} block={block} spec={p} />)
          )}
        </div>
      </div>

      <div className="mt-auto border-t border-line p-4">
        <Button
          data-testid="inspector-delete"
          variant="danger"
          className="w-full"
          onClick={handleDelete}
        >
          Delete block
        </Button>
      </div>
    </div>
  );
}
import { useState } from "react";
import { Field } from "../ui/Field";
import {
  TextInput,
  TextArea,
  NumberInput,
  Slider,
  Select,
  ChipSelect,
  Toggle,
  ListEditor,
} from "../ui/controls";
import { Button } from "../ui/Button";
import { dataflowStore } from "./store";
import { api } from "@/lib/api";
import { useSettings } from "@/lib/settings";
import type { ParamSpec, WorkflowBlock, FileRef } from "@reqflow/core";

export function ParamField({ block, spec }: { block: WorkflowBlock; spec: ParamSpec }) {
  const [error, setError] = useState<string | null>(null);
  const settings = useSettings((s) => s.settings);

  const val = block.params[spec.key];

  const handleChange = (newValue: any) => {
    const err = dataflowStore
      .getState()
      .setParams(block.id, { ...block.params, [spec.key]: newValue });
    setError(err);
  };

  let help = spec.help;
  if (spec.type === "select" && val === "global") {
    if (spec.key === "market") {
      help = `From Settings: ${settings.defaultScope.market}`;
    } else if (spec.key === "vehicle") {
      help = `From Settings: ${settings.defaultScope.vehicleLine}`;
    }
  }

  const renderControl = (id: string) => {
    switch (spec.type) {
      case "text":
        return (
          <TextInput
            id={id}
            value={(val as string) ?? spec.default}
            onChange={handleChange}
            placeholder={spec.placeholder}
            maxLength={spec.maxLength}
          />
        );
      case "textarea":
        return (
          <TextArea
            id={id}
            value={(val as string) ?? spec.default}
            onChange={handleChange}
            placeholder={spec.placeholder}
            maxLength={spec.maxLength}
          />
        );
      case "number":
        return (
          <NumberInput
            id={id}
            value={(val as number) ?? spec.default}
            onChange={handleChange}
            min={spec.min}
            max={spec.max}
            step={spec.step}
            unit={spec.unit}
          />
        );
      case "slider":
        return (
          <Slider
            id={id}
            value={(val as number) ?? spec.default}
            onChange={handleChange}
            min={spec.min}
            max={spec.max}
            step={spec.step}
            unit={spec.unit}
          />
        );
      case "select":
        return (
          <Select
            id={id}
            value={(val as string) ?? spec.default}
            onChange={handleChange}
            options={spec.options}
          />
        );
      case "multiselect":
        return (
          <ChipSelect
            id={id}
            value={(val as string[]) ?? spec.default}
            onChange={handleChange}
            options={spec.options}
          />
        );
      case "toggle":
        return (
          <div className="flex items-center justify-between">
            <span className="text-sm font-medium text-ink">{spec.label}</span>
            <Toggle id={id} value={(val as boolean) ?? spec.default} onChange={handleChange} />
          </div>
        );
      case "list":
        return (
          <ListEditor
            id={id}
            value={(val as string[]) ?? spec.default}
            onChange={handleChange}
            minItems={spec.minItems}
            maxItems={spec.maxItems}
            itemPlaceholder={spec.itemPlaceholder}
          />
        );
      case "file": {
        const fileRef = val as FileRef | null;
        return (
          <div className="flex items-center justify-between gap-2">
            <span className="truncate text-sm text-ink">
              {fileRef ? fileRef.name : "No file chosen"}
            </span>
            <div className="flex gap-2">
              <Button
                id={id}
                variant={fileRef ? "secondary" : "primary"}
                onClick={async () => {
                  try {
                    const res = await api.files.import();
                    if (res) {
                      handleChange({ fileId: res.id, name: res.name });
                    }
                  } catch (e: any) {
                    if (e.code === "not_implemented") {
                      setError("File import isn't built yet (WS1/WS5).");
                    } else {
                      setError(e.message || "Failed to import file.");
                    }
                  }
                }}
              >
                Choose file…
              </Button>
              {fileRef && (
                <Button variant="danger" onClick={() => handleChange(null)}>
                  Remove
                </Button>
              )}
            </div>
          </div>
        );
      }
      default:
        return null;
    }
  };

  if (spec.type === "toggle") {
    return (
      <Field error={error} help={help} label={spec.label}>
        {(id) => renderControl(id)}
      </Field>
    );
  }

  return (
    <Field label={spec.label} error={error} help={help}>
      {(id) => renderControl(id)}
    </Field>
  );
}
import type { PaletteBlockKind, BoundaryBlockKind } from "@reqflow/core";
