          <Button
            data-testid="inspector-open-inner"
            variant="secondary"
            onClick={() => dataflowStore.getState().openInner(block.id)}
          >
            Open its workplace ({innerCount})
          </Button>
        )}

        <div className="flex flex-col gap-4">
          <h3 className="text-sm font-medium text-ink">Parameters</h3>
          {spec!.params.length === 0 ? (
            <div className="text-sm text-muted">
              No parameters. Build this block's logic in its workplace.
            </div>
          ) : (
            spec!.params
              .filter((p) => isParamVisible(p, block.params))
              .map((p) => <ParamField key={p.key} block={block} spec={p} />)
          )}
        </div>
      </div>

      <div className="mt-auto border-t border-line p-4">
        <Button
          data-testid="inspector-delete"
          variant="danger"
          className="w-full"
          onClick={handleDelete}
        >
          Delete block
        </Button>
      </div>
    </div>
  );
}
import { useState } from "react";
import { Field } from "../ui/Field";
import {
  TextInput,
  TextArea,
  NumberInput,
  Slider,
  Select,
  ChipSelect,
  Toggle,
  ListEditor,
} from "../ui/controls";
import { Button } from "../ui/Button";
import { dataflowStore } from "./store";
import { api } from "@/lib/api";
import { useSettings } from "@/lib/settings";
import type { ParamSpec, WorkflowBlock, FileRef } from "@reqflow/core";

export function ParamField({ block, spec }: { block: WorkflowBlock; spec: ParamSpec }) {
  const [error, setError] = useState<string | null>(null);
  const settings = useSettings((s) => s.settings);

  const val = block.params[spec.key];

  const handleChange = (newValue: any) => {
    const err = dataflowStore
      .getState()
      .setParams(block.id, { ...block.params, [spec.key]: newValue });
    setError(err);
  };

  let help = spec.help;
  if (spec.type === "select" && val === "global") {
    if (spec.key === "market") {
      help = `From Settings: ${settings.defaultScope.market}`;
    } else if (spec.key === "vehicle") {
      help = `From Settings: ${settings.defaultScope.vehicleLine}`;
    }
  }

  const renderControl = (id: string) => {
    switch (spec.type) {
      case "text":
        return (
          <TextInput
            id={id}
            value={(val as string) ?? spec.default}
            onChange={handleChange}
            placeholder={spec.placeholder}
            maxLength={spec.maxLength}
          />
        );
      case "textarea":
        return (
          <TextArea
            id={id}
            value={(val as string) ?? spec.default}
            onChange={handleChange}
            placeholder={spec.placeholder}
            maxLength={spec.maxLength}
          />
        );
      case "number":
        return (
          <NumberInput
            id={id}
            value={(val as number) ?? spec.default}
            onChange={handleChange}
            min={spec.min}
            max={spec.max}
            step={spec.step}
            unit={spec.unit}
          />
        );
      case "slider":
        return (
          <Slider
            id={id}
            value={(val as number) ?? spec.default}
            onChange={handleChange}
            min={spec.min}
            max={spec.max}
            step={spec.step}
            unit={spec.unit}
          />
        );
      case "select":
        return (
          <Select
            id={id}
            value={(val as string) ?? spec.default}
            onChange={handleChange}
            options={spec.options}
          />
        );
      case "multiselect":
        return (
          <ChipSelect
            id={id}
            value={(val as string[]) ?? spec.default}
            onChange={handleChange}
            options={spec.options}
          />
        );
      case "toggle":
        return (
          <div className="flex items-center justify-between">
            <span className="text-sm font-medium text-ink">{spec.label}</span>
            <Toggle id={id} value={(val as boolean) ?? spec.default} onChange={handleChange} />
          </div>
        );
      case "list":
        return (
          <ListEditor
            id={id}
            value={(val as string[]) ?? spec.default}
            onChange={handleChange}
            minItems={spec.minItems}
            maxItems={spec.maxItems}
            itemPlaceholder={spec.itemPlaceholder}
          />
        );
      case "file": {
        const fileRef = val as FileRef | null;
        return (
          <div className="flex items-center justify-between gap-2">
            <span className="truncate text-sm text-ink">
              {fileRef ? fileRef.name : "No file chosen"}
            </span>
            <div className="flex gap-2">
              <Button
                id={id}
                variant={fileRef ? "secondary" : "primary"}
                onClick={async () => {
                  try {
                    const res = await api.files.import();
                    if (res) {
                      handleChange({ fileId: res.id, name: res.name });
                    }
                  } catch (e: any) {
                    if (e.code === "not_implemented") {
                      setError("File import isn't built yet (WS1/WS5).");
                    } else {
                      setError(e.message || "Failed to import file.");
                    }
                  }
                }}
              >
                Choose file…
              </Button>
              {fileRef && (
                <Button variant="danger" onClick={() => handleChange(null)}>
                  Remove
                </Button>
              )}
            </div>
          </div>
        );
      }
      default:
        return null;
    }
  };

  if (spec.type === "toggle") {
    return (
      <Field error={error} help={help} label={spec.label}>
        {(id) => renderControl(id)}
      </Field>
    );
  }

  return (
    <Field label={spec.label} error={error} help={help}>
      {(id) => renderControl(id)}
    </Field>
  );
}
