import type { WorkflowGraph } from "@reqflow/core";
import type { DataflowState, XY } from "./store";

/** Size of a block before React Flow has measured it (BlockNode is w-56). */
export const DEFAULT_BLOCK_SIZE = { width: 224, height: 120 };
const GAP = 24;

/**
 * Where to put a block added by click: the free spot nearest to `center` (top-left corner
 * coordinates), searched ring by ring on a grid one block wide/tall, so blocks never stack.
 */
export function findFreePosition(
  graph: WorkflowGraph,
  measured: DataflowState["measured"],
  center: XY,
): XY {
  const { width, height } = DEFAULT_BLOCK_SIZE;
  const start = { x: center.x - width / 2, y: center.y - height / 2 };
  const boxes = graph.blocks.map((b) => ({
    x: b.position.x,
    y: b.position.y,
    ...(measured[b.id] ?? DEFAULT_BLOCK_SIZE),
  }));
  const free = (p: XY) =>
    boxes.every(
      (b) =>
        p.x + width + GAP <= b.x ||
        b.x + b.width + GAP <= p.x ||
        p.y + height + GAP <= b.y ||
        b.y + b.height + GAP <= p.y,
    );
  const stepX = width + GAP;
  const stepY = height + GAP;
  for (let ring = 0; ring <= 12; ring++) {
    for (let dy = -ring; dy <= ring; dy++) {
      for (let dx = -ring; dx <= ring; dx++) {
        if (Math.max(Math.abs(dx), Math.abs(dy)) !== ring) continue; // only this ring's cells
        const p = { x: start.x + dx * stepX, y: start.y + dy * stepY };
        if (free(p)) return p;
      }
    }
  }
  return start; // a very crowded workplace: overlap rather than fail
}
EOF
cat > layout.test.ts <<'EOF'
import { createBlock, type WorkflowGraph } from "@reqflow/core";
import { describe, expect, it } from "vitest";
import { DEFAULT_BLOCK_SIZE, findFreePosition } from "./layout";

const { width, height } = DEFAULT_BLOCK_SIZE;
const overlaps = (a: { x: number; y: number }, b: { x: number; y: number }) =>
  Math.abs(a.x - b.x) < width && Math.abs(a.y - b.y) < height;

describe("findFreePosition", () => {
  it("centres the first block on the given point", () => {
    const empty: WorkflowGraph = { blocks: [], edges: [] };
    expect(findFreePosition(empty, {}, { x: 500, y: 300 })).toEqual({
      x: 500 - width / 2,
      y: 300 - height / 2,
    });
  });

  it("never stacks blocks added one after another", () => {
    let graph: WorkflowGraph = { blocks: [], edges: [] };
    const placed: { x: number; y: number }[] = [];
    for (let i = 0; i < 12; i++) {
      const p = findFreePosition(graph, {}, { x: 0, y: 0 });
      for (const q of placed) expect(overlaps(p, q)).toBe(false);
      placed.push(p);
      graph = { ...graph, blocks: [...graph.blocks, createBlock("hil", { id: `h${i}`, position: p })] };
    }
  });

  it("respects measured sizes of tall blocks", () => {
    const tall = createBlock("ai_splitter", { id: "s", position: { x: -112, y: -60 } });
    const graph: WorkflowGraph = { blocks: [tall], edges: [] };
    const p = findFreePosition(graph, { s: { width: 224, height: 600 } }, { x: 0, y: 0 });
    expect(p.x === -112 && p.y > -60 && p.y < 540).toBe(false);
  });
});
EOF
