@import "tailwindcss";
@import "@xyflow/react/dist/style.css";

/* Dark mode follows the `data-theme` attribute on <html> (set from Settings → App → Theme). */
@custom-variant dark (&:where([data-theme="dark"], [data-theme="dark"] *));

/*
 * Design tokens — WS4 owns the visual system. Use these (bg-panel, border-line, text-muted, …)
 * instead of hard-coded colors, so light and dark mode both work.
 */
@theme static {
  --font-sans:
    -apple-system, BlinkMacSystemFont, "Segoe UI", system-ui, Roboto, "Helvetica Neue", Arial,
    sans-serif;

  --color-brand: #1c69d4; /* BMW blue */
  --color-brand-soft: #e8f0fb;
  --color-canvas: #f3f4f6; /* app background behind the panels */
  --color-dot: #d3d7dd; /* dot grid on the canvas */
  --color-panel: #ffffff;
  --color-panel-2: #f7f8fa; /* inset areas, inputs */
  --color-line: #d6dae0;
  --color-line-strong: #b4bbc5;
  --color-ink: #1b2230;
  --color-muted: #5f6b7a;
  --color-danger: #c62828;
  --color-danger-soft: #fdecec;
  --color-warn: #a35f00;
  --color-warn-soft: #fff4e0;
  --color-ok: #1b7f4b;

  /* Block groups (see BlockGroup in @reqflow/core) */
  --color-group-structure: #64748b;
  --color-group-source: #1c69d4;
  --color-group-ai: #7c3aed;
  --color-group-human: #d97706;
  --color-group-output: #059669;
}

:root[data-theme="dark"] {
  color-scheme: dark;
  --color-brand: #4d8fe8;
  --color-brand-soft: #18273d;
  --color-canvas: #0d1015;
  --color-dot: #262c35;
  --color-panel: #161a21;
  --color-panel-2: #1c2129;
  --color-line: #2b323d;
  --color-line-strong: #3d4653;
  --color-ink: #e5e8ed;
  --color-muted: #98a2b0;
  --color-danger: #f07171;
  --color-danger-soft: #3a1c1f;
  --color-warn: #f0b04d;
  --color-warn-soft: #36290f;
  --color-ok: #4cc287;
  --color-group-structure: #94a3b8;
  --color-group-source: #4d8fe8;
  --color-group-ai: #a78bfa;
  --color-group-human: #f59e0b;
  --color-group-output: #34d399;
}

html,
body,
#root {
  height: 100%;
  margin: 0;
  background: var(--color-canvas);
  color: var(--color-ink);

