python3 - <<'EOF'
from pathlib import Path
p = Path("globals.css"); s = p.read_text()
start = s.index("@theme static {")
end = s.index("html,\nbody,")
s = s[:start] + '''@theme static {
  --font-sans:
    -apple-system, BlinkMacSystemFont, "Segoe UI", system-ui, Roboto, "Helvetica Neue", Arial,
    sans-serif;

  /* BMW M colorway: the three M stripe colours (same in both themes) on carbon neutrals. */
  --color-m-light: #81c4ff;
  --color-m-dark: #16588e;
  --color-m-red: #e7222e;

  --color-brand: #16588e; /* accent for text, borders, focus rings: M dark blue */
  --color-brand-fill: #16588e; /* filled controls with white content (primary button, toggle) */
  --color-brand-soft: #e6f0f9;
  --color-canvas: #f2f3f4; /* app background behind the panels */
  --color-dot: #d2d5d9; /* dot grid on the canvas */
  --color-panel: #ffffff;
  --color-panel-2: #f6f7f8; /* inset areas, inputs */
  --color-line: #d9dcdf;
  --color-line-strong: #b3b8be;
  --color-ink: #111214;
  --color-muted: #5d636b;
  --color-danger: #c81e28; /* M red, a shade darker so small text stays readable */
  --color-danger-soft: #fdecec;
  --color-warn: #a35f00;
  --color-warn-soft: #fff4e0;
  --color-ok: #1b7f4b;

  /* Block groups (see BlockGroup in @reqflow/core), drawn from the M stripe */
  --color-group-structure: #6b7078;
  --color-group-source: #2b8ee6; /* M light blue, deepened for white backgrounds */
  --color-group-ai: #16588e; /* M dark blue */
  --color-group-human: #e7222e; /* M red: a person has to act here */
  --color-group-output: #111214; /* the car itself */
}

:root[data-theme="dark"] {
  color-scheme: dark;
  --color-brand: #81c4ff; /* M light blue */
  --color-brand-fill: #1f6fb5;
  --color-brand-soft: #132638;
  --color-canvas: #08090a;
  --color-dot: #1f2226;
  --color-panel: #121315;
  --color-panel-2: #191a1d;
  --color-line: #25282c;
  --color-line-strong: #3a3e44;
  --color-ink: #f2f3f5;
  --color-muted: #979ca4;
  --color-danger: #ff5a63;
  --color-danger-soft: #3a1517;
  --color-warn: #f0b04d;
  --color-warn-soft: #36290f;
  --color-ok: #4cc287;
  --color-group-structure: #8d939b;
  --color-group-source: #81c4ff;
  --color-group-ai: #4b8fd1; /* M dark blue, lifted for dark backgrounds */
  --color-group-human: #ff4752;
  --color-group-output: #f2f3f5;
}

''' + s[end:]
p.write_text(s)

def edit(path, pairs):
    p = Path(path); s = p.read_text()
    for old, new in pairs:
        assert old in s, (path, old[:70])
        s = s.replace(old, new, 1)
    p.write_text(s)
edit("components/ui/Button.tsx", [('primary: "bg-brand text-white hover:brightness-110 border-transparent",', 'primary: "bg-brand-fill text-white hover:brightness-110 border-transparent",')])
edit("components/ui/controls.tsx", [('props.value ? "bg-brand" : "bg-line-strong",', 'props.value ? "bg-brand-fill" : "bg-line-strong",')])
EOF
cat > components/ui/MStripe.tsx <<'EOF'
import { cx } from "@/lib/cx";

/**
 * The BMW M stripe: light blue, dark blue, red. `bar` is a thin full-width line (active tab),
 * `badge` the three slanted strokes (next to the car name).
 */
export function MStripe({
  variant = "bar",
  className,
}: {
  variant?: "bar" | "badge";
  className?: string;
}) {
  const colors = ["bg-m-light", "bg-m-dark", "bg-m-red"];
  return variant === "bar" ? (
    <span aria-hidden="true" className={cx("flex h-[3px] overflow-hidden rounded-full", className)}>
      {colors.map((c) => (
        <span key={c} className={cx("flex-1", c)} />
      ))}
    </span>
  ) : (
    <span aria-hidden="true" className={cx("inline-flex h-4 gap-[3px]", className)}>
      {colors.map((c) => (
        <span key={c} className={cx("w-[5px] -skew-x-[20deg]", c)} />
      ))}
    </span>
  );
}
EOF
cat components/shell/BottomNav.tsx | sed -n 20,60p

