export function BottomNav() {
  return (
    <nav aria-label="Pages" className="grid h-16 shrink-0 grid-cols-3 gap-2">
      {TABS.map(({ to, label, hint, Icon }, i) => (
        <NavLink
          key={to}
          to={to}
          data-testid={`tab-${to.slice(1)}`}
          className={({ isActive }) =>
            cx(
              "group flex items-center gap-3 rounded-xl border px-5 transition",
              "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-brand",
              isActive
                ? "border-brand bg-brand-soft text-brand"
                : "border-line bg-panel text-ink hover:border-line-strong",
            )
          }
        >
          {({ isActive }) => (
            <>
              <Icon className="size-5 shrink-0" />
              <span className="min-w-0">
                <span className="block text-[15px] font-medium">{label}</span>
                <span
                  className={cx(
                    "block truncate text-xs",
                    isActive ? "text-brand/80" : "text-muted",
                  )}
                >
                  {hint}
                </span>
              </span>
              <kbd className="ml-auto hidden font-sans text-xs text-muted lg:block">
                {MOD}
                {i + 1}
              </kbd>
            </>
          )}
        </NavLink>
      ))}
    </nav>

